const demoCatalog = [
  { id: 1, name: "Fazenda de demonstração", company: "Registro fictício", city: "Rio Verde", state: "GO", products: "Soja; milho", categoriesJson: '["Produtor rural"]', tagsJson: '["Demonstração"]', phones: [{ id: 1, original: "Telefone fictício", normalized: null, validationStatus: "review", isPreferred: true, isWhatsapp: true }], private: { favorite: false } },
  { id: 2, name: "Cooperativa de demonstração", company: "Registro fictício", city: "Cascavel", state: "PR", products: "Milho", categoriesJson: '["Comprador de grãos"]', tagsJson: '["Demonstração"]', phones: [], private: null },
];
const states = ["AC", "AL", "AM", "AP", "BA", "CE", "DF", "ES", "GO", "MA", "MG", "MS", "MT", "PA", "PB", "PE", "PI", "PR", "RJ", "RN", "RO", "RR", "RS", "SC", "SE", "SP", "TO"];

type PhoneForm = { original: string; isWhatsapp: boolean; isPreferred: boolean };
const emptyPhone = (): PhoneForm => ({ original: "", isWhatsapp: true, isPreferred: false });
const emptyContact = () => ({ name: "", company: "", email: "", city: "", state: "", addressOriginal: "", notes: "", categories: "", tags: "", doNotContact: false, phones: [emptyPhone()] });
function parseJsonList(value: string | null | undefined): string[] { try { return JSON.parse(value || "[]"); } catch { return []; } }
function formatNumber(value: number) { return value.toLocaleString("pt-BR"); }
function formatDate(value: string | Date | null | undefined) { return value ? new Date(value).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }) : "—"; }
function csvCell(value: unknown) {
  const text = String(value ?? "").replace(/\r?\n/g, " ");
  const safe = /^[=+\-@]/.test(text) ? `'${text}` : text;
  return /[;"\n]/.test(safe) ? `"${safe.replace(/"/g, '""')}"` : safe;
}
function Logo() { return <div className="brand"><span className="brand-mark"><span /><span /></span><span className="brand-name">AGRO<span>LINK</span></span></div>; }
function StatusPill({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "green" | "amber" | "blue" | "gold" }) { return <span className={`status-pill status-${tone}`}>{children}</span>; }
function EmptyState({ icon: Icon, title, description, action }: { icon: typeof Database; title: string; description: string; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={22} /></div><h3>{title}</h3><p>{description}</p>{action}</div>; }
function DemoBanner() { return <div className="demo-banner"><ShieldCheck size={15} /><span>Modo demonstração — os registros são fictícios e nenhum dado é salvo.</span><span className="demo-badge">DEMO</span></div>; }

function DashboardOverview({ demo, onNavigate }: { demo: boolean; onNavigate: (view: string) => void }) {
  const summary = trpc.catalog.summary.useQuery(undefined, { enabled: !demo, retry: false });
  const dashboard = trpc.dashboard.overview.useQuery(undefined, { enabled: !demo, retry: false });
  const catalog = summary.data;
  const own = dashboard.data;
  const access = demo ? false : Boolean(catalog?.access);
  const categories = demo ? [] : catalog?.categories || [];
  const max = Math.max(...categories.map(item => item.value), 1);
  return <div className="view-stack"><section className="hero-strip catalog-hero"><div><p className="eyebrow">BASE AGROLINK</p><h1>Encontre o contato que abre a próxima conversa.</h1><p className="hero-copy">Pesquise por categoria, estado, cidade ou produto. Seus favoritos e anotações ficam só na sua organização.</p></div><button className="hero-action" onClick={() => onNavigate("catalog")}><Search size={17} /> Buscar na base</button></section><div className="kpi-grid"><button className="kpi-card kpi-green" onClick={() => onNavigate("catalog")}><div className="kpi-top"><span className="eyebrow">CONTATOS PUBLICADOS</span><Database size={17} /></div><strong>{demo ? "—" : formatNumber(catalog?.total || 0)}</strong><span className="kpi-detail">Consultar Base AGROLINK <ArrowUpRight size={13} /></span></button><button className="kpi-card kpi-gold" onClick={() => onNavigate("catalog")}><div className="kpi-top"><span className="eyebrow">CATEGORIAS</span><Tag size={17} /></div><strong>{demo ? "—" : categories.length}</strong><span className="kpi-detail">Explorar categorias <ArrowUpRight size={13} /></span></button><button className="kpi-card kpi-blue" onClick={() => onNavigate("catalog")}><div className="kpi-top"><span className="eyebrow">MEUS FAVORITOS</span><Star size={17} /></div><strong>{demo ? "—" : formatNumber(own?.favoriteContacts || 0)}</strong><span className="kpi-detail">Privados por organização <ArrowUpRight size={13} /></span></button><button className="kpi-card kpi-amber" onClick={() => onNavigate("private")}><div className="kpi-top"><span className="eyebrow">MEUS CONTATOS</span><Users size={17} /></div><strong>{demo ? "—" : formatNumber(own?.privateContacts || 0)}</strong><span className="kpi-detail">Importações particulares <ArrowUpRight size={13} /></span></button></div><div className="content-grid dashboard-grid"><section className="panel chart-panel"><div className="panel-heading"><div><p className="eyebrow">BASE AGROLINK</p><h2>Contatos por categoria</h2></div><button className="text-button" onClick={() => onNavigate("catalog")}>Abrir base <ArrowUpRight size={14} /></button></div>{demo ? <EmptyState icon={ShieldCheck} title="Demonstração não contabilizada" description="Os registros fictícios servem apenas para mostrar a interface. A quantidade real aparece após a liberação da base." /> : !access ? <EmptyState icon={ShieldCheck} title="Acesso ainda não liberado" description="A autenticação sozinha não libera a base paga. Quando a assinatura ou liberação válida existir, os contatos aparecerão aqui." /> : categories.length ? <div className="bar-list">{categories.slice(0, 5).map((item, index) => <div className="bar-row" key={item.name}><div className="bar-label"><span>{item.name}</span><strong>{formatNumber(item.value)}</strong></div><div className="bar-track"><span style={{ width: `${Math.max(8, (item.value / max) * 100)}%` }} /></div></div>)}</div> : <EmptyState icon={Database} title="Base aguardando publicação" description="A equipe administradora ainda não publicou contatos no catálogo." />}</section><section className="panel attention-panel"><div className="panel-heading"><div><p className="eyebrow">SEU ESPAÇO PRIVADO</p><h2>Organize seu trabalho</h2></div></div><div className="attention-list"><button onClick={() => onNavigate("catalog")}><span className="attention-dot green" /><span><strong>Base AGROLINK</strong><small>Pesquisa por categoria e localização</small></span><ChevronRight size={17} /></button><button onClick={() => onNavigate("private")}><span className="attention-dot amber" /><span><strong>Meus contatos</strong><small>Cadastros, etiquetas e exportação privada</small></span><ChevronRight size={17} /></button><button onClick={() => onNavigate("crm")}><span className="attention-dot blue" /><span><strong>Tarefas e CRM</strong><small>Próximo contato e acompanhamento</small></span><ChevronRight size={17} /></button></div></section></div></div>;
}

function CatalogView({ demo, onNavigate }: { demo: boolean; onNavigate: (view: string) => void }) {
  const [search, setSearch] = useState(""); const [state, setState] = useState(""); const [city, setCity] = useState(""); const [category, setCategory] = useState(""); const [product, setProduct] = useState(""); const [favoritesOnly, setFavoritesOnly] = useState(false); const [page, setPage] = useState(0); const [composerContact, setComposerContact] = useState<any>(null);
  const catalog = trpc.catalog.list.useQuery({ search: search || undefined, state: state || undefined, city: city || undefined, category: category || undefined, product: product || undefined, favoritesOnly, limit: 25, offset: page * 25 }, { enabled: !demo, retry: false });
  const summary = trpc.catalog.summary.useQuery(undefined, { enabled: !demo, retry: false }); const templates = trpc.templates.list.useQuery(undefined, { enabled: !demo, retry: false }); const org = trpc.organization.current.useQuery(undefined, { enabled: !demo, retry: false });
  const favorite = trpc.catalog.favorite.useMutation({ onSuccess: () => catalog.refetch() }); const noteMutation = trpc.catalog.note.useMutation({ onSuccess: () => { catalog.refetch(); toast.success("Anotação privada salva."); } }); const whatsapp = trpc.activity.whatsappOpened.useMutation();
  const rows: any[] = demo ? demoCatalog.filter(row => !search || `${row.name} ${row.city} ${row.state} ${row.products}`.toLowerCase().includes(search.toLowerCase())).filter(row => !state || row.state === state) : catalog.data?.rows || [];
  const categories = demo ? ["Produtor rural", "Compradores de grãos", "Transportadoras"] : (summary.data?.categories || []).map(item => item.name);
  const clear = () => { setSearch(""); setState(""); setCity(""); setCategory(""); setProduct(""); setFavoritesOnly(false); setPage(0); };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">CATÁLOGO INCLUÍDO NO ACESSO</p><h1>Base AGROLINK</h1><p>Encontre contatos publicados pela plataforma. O registro central é somente para consulta.</p></div><div className="title-actions"><Button variant="outline" onClick={() => onNavigate("templates")}><MessageCircle size={16} /> Mensagens</Button><Button onClick={() => onNavigate("private")}><Users size={16} /> Meus contatos</Button></div></div>{!demo && catalog.data?.access === false ? <section className="panel locked-panel"><ShieldCheck size={24} /><div><h2>Acesso à Base AGROLINK não liberado</h2><p>O plano precisa incluir o catálogo e a assinatura ou liberação manual precisa estar válida.</p></div></section> : <><section className="catalog-search-hero"><div><p className="eyebrow">BUSCA EM DESTAQUE</p><h2>Quem você quer encontrar?</h2><p>Use nome, telefone, cidade, estado, categoria ou produto.</p></div><div className="catalog-search-field"><Search size={19} /><input value={search} onChange={event => { setSearch(event.target.value); setPage(0); }} placeholder="Buscar na Base AGROLINK" /></div></section><div className="catalog-filters"><select value={category} onChange={event => { setCategory(event.target.value); setPage(0); }}><option value="">Todas as categorias</option>{categories.map(item => <option key={item}>{item}</option>)}</select><select value={state} onChange={event => { setState(event.target.value); setPage(0); }}><option value="">Todos os estados</option>{states.map(item => <option key={item}>{item}</option>)}</select><input value={city} onChange={event => { setCity(event.target.value); setPage(0); }} placeholder="Cidade" /><input value={product} onChange={event => { setProduct(event.target.value); setPage(0); }} placeholder="Produto ou atividade" /><button className={`filter-button ${favoritesOnly ? "active" : ""}`} onClick={() => { setFavoritesOnly(value => !value); setPage(0); }}><Star size={14} /> Favoritos</button><button className="filter-button" onClick={clear}><X size={14} /> Limpar</button></div><section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>Contato</th><th>Categoria</th><th>Localização</th><th>Telefone</th><th>Privado</th><th>Ações</th></tr></thead><tbody>{rows.length ? rows.map(row => { const cats = row.categories || parseJsonList(row.categoriesJson); const phone = row.phones?.find((item: any) => item.isPreferred) || row.phones?.[0]; const isFav = Boolean(row.private?.favorite); return <tr key={row.id}><td><div className="contact-cell"><span className="avatar">{row.name.slice(0, 1)}</span><span><strong>{row.name}</strong><small>{row.company || "Registro da Base AGROLINK"}</small></span></div></td><td><StatusPill tone="green">{cats[0] || "Sem categoria"}</StatusPill></td><td>{row.city || "—"}{row.state ? `, ${row.state}` : ""}</td><td>{phone?.normalized && phone.isWhatsapp !== false && !row.doNotContact ? <button className="whatsapp-link" onClick={() => setComposerContact(row)}><MessageCircle size={14} /> Abrir WhatsApp</button> : <StatusPill tone="amber">{row.doNotContact ? "Não contatar" : phone?.normalized ? "Sem WhatsApp configurado" : "Completar número"}</StatusPill>}</td><td><button className={`favorite-button ${isFav ? "active" : ""}`} onClick={() => demo ? toast.info("Favoritos da demonstração não são salvos.") : favorite.mutate({ catalogContactId: row.id, favorite: !isFav })}><Star size={15} fill={isFav ? "currentColor" : "none"} /> {isFav ? "Favorito" : "Salvar"}</button></td><td><button className="icon-button" onClick={() => { const note = window.prompt("Anotação privada (opcional):", row.private?.notes || ""); if (note !== null && !demo) noteMutation.mutate({ catalogContactId: row.id, notes: note }); }} aria-label={`Anotar ${row.name}`}><MoreHorizontal size={18} /></button></td></tr>; }) : <tr><td colSpan={6}><EmptyState icon={Database} title="Nenhum contato encontrado" description={demo ? "A demonstração usa registros fictícios identificados e não contabilizados." : "Ajuste os filtros ou verifique se sua assinatura possui acesso."} /></td></tr>}</tbody></table></div><div className="table-footer"><span>{demo ? "Demonstração sem contagem comercial" : `${formatNumber(catalog.data?.total || 0)} resultado(s)`}</span><div><button className="pager-button" disabled={page === 0} onClick={() => setPage(Math.max(0, page - 1))}><ChevronLeft size={16} /></button><button className="pager-button" disabled={rows.length < 25 || demo} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></button></div></div></section></>}<WhatsappComposer open={Boolean(composerContact)} demo={demo} contact={composerContact} templates={templates.data || []} defaultMessage={org.data?.organization?.defaultMessage} userName={org.data?.user?.name} organizationName={org.data?.organization?.name} onClose={() => setComposerContact(null)} onOpened={phone => { if (!demo && composerContact) whatsapp.mutate({ catalogContactId: composerContact.id, phone }); }} /></div>;
}

function PrivateContactsView({ demo, onNavigate }: { demo: boolean; onNavigate: (view: string) => void }) {
  const [search, setSearch] = useState(""); const [tagFilter, setTagFilter] = useState(""); const [page, setPage] = useState(0); const [showForm, setShowForm] = useState(false); const [editing, setEditing] = useState<any>(null); const [form, setForm] = useState(emptyContact()); const [composerContact, setComposerContact] = useState<any>(null);
  const query = trpc.contacts.list.useQuery({ search: search || undefined, tag: tagFilter || undefined, limit: 25, offset: page * 25 }, { enabled: !demo, retry: false }); const templates = trpc.templates.list.useQuery(undefined, { enabled: !demo, retry: false }); const org = trpc.organization.current.useQuery(undefined, { enabled: !demo, retry: false }); const canManage = demo || org.data?.member?.role === "owner" || org.data?.member?.role === "admin"; const whatsapp = trpc.activity.whatsappOpened.useMutation();
  const reset = () => setForm(emptyContact());
  const create = trpc.contacts.create.useMutation({ onSuccess: () => { query.refetch(); setShowForm(false); reset(); toast.success("Contato particular criado."); }, onError: error => toast.error(error.message) });
  const update = trpc.contacts.update.useMutation({ onSuccess: () => { query.refetch(); setShowForm(false); setEditing(null); toast.success("Contato particular atualizado."); }, onError: error => toast.error(error.message) });
  const exportMutation = trpc.contacts.export.useMutation({ onSuccess: rows => { const csv = ["nome;empresa;telefone;whatsapp;email;cidade;uf;categorias;etiquetas"].concat(rows.map(row => [row.name, row.company, row.phones.map(phone => phone.original).join(","), row.phones.filter(phone => phone.isWhatsapp).map(phone => phone.original).join(","), row.email, row.city, row.state, parseJsonList(row.categoriesJson).join(","), parseJsonList(row.tagsJson).join(",")].map(csvCell).join(";"))).join("\n"); const url = URL.createObjectURL(new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "agrolink-meus-contatos.csv"; anchor.click(); URL.revokeObjectURL(url); toast.success("Exportação particular criada."); }, onError: error => toast.error(error.message) });
  const rows: any[] = demo ? [] : query.data?.rows || [];
  const save = () => { if (!form.name.trim()) return toast.error("Informe o nome do contato."); if (demo) return toast.info("O modo demonstração não salva contatos."); const payload = { ...form, categories: form.categories.split(/[;,]+/).map(item => item.trim()).filter(Boolean), tags: form.tags.split(/[;,]+/).map(item => item.trim()).filter(Boolean), phones: form.phones.filter(phone => phone.original.trim()) }; if (editing) update.mutate({ contactId: editing.id, ...payload }); else create.mutate(payload); };
  const editRow = (row: any) => { setEditing(row); setForm({ name: row.name, company: row.company || "", email: row.email || "", city: row.city || "", state: row.state || "", addressOriginal: row.addressOriginal || "", notes: row.notes || "", categories: parseJsonList(row.categoriesJson).join(", "), tags: parseJsonList(row.tagsJson).join(", "), doNotContact: Boolean(row.doNotContact), phones: row.phones?.length ? row.phones.map((phone: any) => ({ original: phone.original, isWhatsapp: phone.isWhatsapp, isPreferred: phone.isPreferred })) : [emptyPhone()] }); setShowForm(true); };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">DADOS DA SUA ORGANIZAÇÃO</p><h1>Meus contatos</h1><p>Cadastros, etiquetas e importações particulares, separados da Base AGROLINK.</p></div><div className="title-actions">{canManage && <><Button variant="outline" onClick={() => onNavigate("imports")}><CloudUpload size={16} /> Importar lista</Button><Button onClick={() => { setEditing(null); reset(); setShowForm(true); }}><Plus size={16} /> Novo contato</Button></>}</div></div>{canManage && showForm && <section className="panel contact-form-panel"><div className="panel-heading"><div><p className="eyebrow">{editing ? "EDITAR" : "CADASTRO MANUAL"}</p><h2>{editing ? "Editar contato particular" : "Novo contato particular"}</h2></div><button className="icon-button" onClick={() => setShowForm(false)}><X size={18} /></button></div><div className="form-grid contact-form-grid"><label><span>Nome</span><input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></label><label><span>Empresa ou propriedade</span><input value={form.company} onChange={event => setForm({ ...form, company: event.target.value })} /></label><label><span>E-mail</span><input value={form.email} onChange={event => setForm({ ...form, email: event.target.value })} /></label><label><span>Cidade</span><input value={form.city} onChange={event => setForm({ ...form, city: event.target.value })} /></label><label><span>UF</span><select value={form.state} onChange={event => setForm({ ...form, state: event.target.value })}><option value="">Selecione</option>{states.map(item => <option key={item}>{item}</option>)}</select></label><label><span>Categorias</span><input value={form.categories} onChange={event => setForm({ ...form, categories: event.target.value })} placeholder="Ex.: produtor rural, comprador" /></label><label><span>Etiquetas</span><input value={form.tags} onChange={event => setForm({ ...form, tags: event.target.value })} placeholder="Ex.: cliente, soja" /></label><label><span>Endereço original</span><input value={form.addressOriginal} onChange={event => setForm({ ...form, addressOriginal: event.target.value })} /></label><label><span>Anotação privada</span><textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} rows={3} /></label><label className="inline-check do-not-contact"><input type="checkbox" checked={form.doNotContact} onChange={event => setForm({ ...form, doNotContact: event.target.checked })} /> Não contatar este registro</label></div><div className="phone-editor"><div className="panel-heading"><div><p className="eyebrow">TELEFONES</p><h3>Um ou mais números</h3></div><button className="filter-button" onClick={() => setForm({ ...form, phones: [...form.phones, emptyPhone()] })}><Plus size={14} /> Adicionar telefone</button></div>{form.phones.map((phone, index) => <div className="phone-editor-row" key={index}><input value={phone.original} placeholder="Telefone original" onChange={event => setForm({ ...form, phones: form.phones.map((item, i) => i === index ? { ...item, original: event.target.value } : item) })} /><label className="inline-check"><input type="checkbox" checked={phone.isWhatsapp} onChange={event => setForm({ ...form, phones: form.phones.map((item, i) => i === index ? { ...item, isWhatsapp: event.target.checked } : item) })} /> WhatsApp pretendido</label><label className="inline-check"><input type="radio" name="preferred-phone" checked={phone.isPreferred} onChange={() => setForm({ ...form, phones: form.phones.map((item, i) => ({ ...item, isPreferred: i === index })) })} /> Preferencial</label>{form.phones.length > 1 && <button className="icon-button" onClick={() => setForm({ ...form, phones: form.phones.filter((_, i) => i !== index) })}><X size={15} /></button>}</div>)}</div><div className="preview-footer"><span><ShieldCheck size={15} /> Número original preservado; incompletos ficam para revisão.</span><Button onClick={save} disabled={create.isPending || update.isPending}>{(create.isPending || update.isPending) && <Loader2 className="spin" size={16} />} Salvar contato</Button></div></section>}<div className="filter-toolbar"><div className="search-field"><Search size={17} /><input value={search} onChange={event => { setSearch(event.target.value); setPage(0); }} placeholder="Buscar nos meus contatos" /></div><input value={tagFilter} onChange={event => { setTagFilter(event.target.value); setPage(0); }} placeholder="Filtrar por etiqueta" /><button className="filter-button" onClick={() => exportMutation.mutate()} disabled={exportMutation.isPending}><Download size={15} /> Exportar particulares</button></div><section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>Contato</th><th>Categoria / etiquetas</th><th>Localização</th><th>Telefone / WhatsApp</th><th>Origem</th><th>Ações</th></tr></thead><tbody>{rows.length ? rows.map(row => { const cats = parseJsonList(row.categoriesJson); const tags = parseJsonList(row.tagsJson); const phone = row.phones?.find((item: any) => item.isPreferred) || row.phones?.[0]; return <tr key={row.id}><td><div className="contact-cell"><button className={`favorite-button ${row.favorite ? "active" : ""}`} onClick={() => update.mutate({ contactId: row.id, favorite: !row.favorite })}><Star size={15} fill={row.favorite ? "currentColor" : "none"} /></button><span className="avatar">{row.name.slice(0, 1)}</span><span><strong>{row.name}</strong><small>{row.company || row.email || "Sem empresa informada"}</small></span></div></td><td><StatusPill tone="green">{cats[0] || "Sem categoria"}</StatusPill><small className="tag-line">{tags.join(" · ") || "Sem etiquetas"}</small></td><td>{row.city || "—"}{row.state ? `, ${row.state}` : ""}</td><td>{phone?.normalized ? <button className="whatsapp-link" onClick={() => setComposerContact(row)}><MessageCircle size={14} /> Abrir WhatsApp</button> : <StatusPill tone="amber">Completar número</StatusPill>}</td><td><StatusPill tone="neutral">{row.origin === "manual" ? "Manual" : "Importação"}</StatusPill></td><td>{canManage && <button className="icon-button" onClick={() => editRow(row)}><Pencil size={16} /></button>}</td></tr>; }) : <tr><td colSpan={6}><EmptyState icon={Users} title="Nenhum contato particular" description="Importe sua rede ou cadastre o primeiro contato. A Base AGROLINK continua separada." action={canManage ? <Button size="sm" onClick={() => { setEditing(null); reset(); setShowForm(true); }}><Plus size={15} /> Cadastrar contato</Button> : undefined} /></td></tr>}</tbody></table></div><div className="table-footer"><span>{formatNumber(query.data?.total || 0)} contato(s) particular(es)</span><div><button className="pager-button" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></button><button className="pager-button" disabled={rows.length < 25} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></button></div></div></section><WhatsappComposer open={Boolean(composerContact)} contact={composerContact} templates={templates.data || []} defaultMessage={org.data?.organization?.defaultMessage} userName={org.data?.user?.name} organizationName={org.data?.organization?.name} onClose={() => setComposerContact(null)} onOpened={phone => { if (!demo && composerContact) whatsapp.mutate({ contactId: composerContact.id, phone }); toast.success("Tentativa de abertura registrada."); }} /></div>;
}

function ImportView({ demo, onNavigate }: { demo: boolean; onNavigate: (view: string) => void }) {
  const [rows, setRows] = useState<RawRow[]>([]); const [headers, setHeaders] = useState<string[]>([]); const [fileName, setFileName] = useState(""); const [sourceType, setSourceType] = useState<"xlsx" | "csv" | "pasted">("xlsx"); const [pasted, setPasted] = useState(""); const [category, setCategory] = useState("Produtor rural"); const [defaultAreaCode, setDefaultAreaCode] = useState(""); const [mapping, setMapping] = useState<Record<string, string | null>>({}); const [batchId, setBatchId] = useState<number | null>(null); const [showPreview, setShowPreview] = useState(false);
  const organization = trpc.organization.current.useQuery(undefined, { enabled: !demo, retry: false }); const canManage = demo || organization.data?.member?.role === "owner" || organization.data?.member?.role === "admin";
  const startImport = trpc.imports.start.useMutation({ onSuccess: result => { setBatchId(result.batchId); toast.success("Importação particular iniciada."); }, onError: error => toast.error(error.message) }); const batchQuery = trpc.imports.status.useQuery({ batchId: batchId || 0 }, { enabled: Boolean(batchId) && !demo, refetchInterval: batchId && !demo ? 1500 : false }); const preview = useMemo(() => rows.slice(0, 5).map(row => mapRow(row, mapping, { category, defaultAreaCode: defaultAreaCode || undefined, usePhonesAsWhatsapp: true })), [rows, mapping, category, defaultAreaCode]);
  if (!demo && organization.data?.member?.role === "operator") return <div className="view-stack"><section className="panel locked-panel"><ShieldCheck size={24} /><div><h2>Importação restrita</h2><p>Somente proprietários e administradores podem cadastrar ou importar contatos particulares.</p></div></section></div>;
  const readFile = async (file: File) => { setFileName(file.name); const workbook = XLSX.read(await file.arrayBuffer(), { type: "array", cellDates: false, raw: false }); const sheet = workbook.Sheets[workbook.SheetNames[0]]; const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" }) as unknown[][]; const first = (matrix[0] || []).map(value => String(value)); const parsed = matrix.slice(1).filter(row => row.some(value => String(value).trim())).map(row => Object.fromEntries(first.map((header, index) => [header, row[index] ?? ""]))); setHeaders(first); setRows(parsed); setMapping(detectMapping(first)); setSourceType(file.name.toLowerCase().endsWith(".csv") ? "csv" : "xlsx"); setShowPreview(true); };
  const preparePasted = () => { const parsed = parsePastedList(pasted); setHeaders(["name"]); setRows(parsed); setMapping({ name: "name" }); setSourceType("pasted"); setFileName("lista colada"); setShowPreview(true); };
  const confirm = () => { if (!rows.length) return toast.info("Envie uma planilha ou cole uma lista."); if (demo) return toast.info("O modo demonstração não grava dados."); startImport.mutate({ fileName, sourceType, rows, mapping, category, countryDialCode: "55", defaultAreaCode: defaultAreaCode || undefined, usePhonesAsWhatsapp: true }); };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">RECURSO COMPLEMENTAR</p><h1>Importar meus contatos</h1><p>Esta lista entra somente na sua organização e nunca na Base AGROLINK central.</p></div><button className="text-button" onClick={() => onNavigate("private")}><Users size={15} /> Ver meus contatos</button></div>{batchQuery.data && <section className="import-progress panel"><div className="progress-heading"><div><p className="eyebrow">LOTE {batchQuery.data.id}</p><h2>{batchQuery.data.fileName || "Importação"}</h2></div><StatusPill tone={batchQuery.data.status === "completed" ? "green" : "blue"}>{batchQuery.data.status === "completed" ? "Concluída" : batchQuery.data.status}</StatusPill></div><div className="progress-track"><span style={{ width: `${batchQuery.data.totalRows ? (batchQuery.data.processedRows / batchQuery.data.totalRows) * 100 : 0}%` }} /></div><div className="progress-meta"><span>{formatNumber(batchQuery.data.processedRows)} de {formatNumber(batchQuery.data.totalRows)} linhas</span><span>{formatNumber(batchQuery.data.createdContacts)} criados · {formatNumber(batchQuery.data.pendingRows)} pendências · {formatNumber(batchQuery.data.rejectedRows)} rejeitados</span></div></section>}{!showPreview ? <div className="import-layout"><section className="panel upload-panel"><div className="upload-symbol"><CloudUpload size={24} /></div><h2>Envie sua lista particular</h2><p>Compatível com XLSX e CSV. Você verá a prévia antes de confirmar.</p><label className="upload-drop"><input type="file" accept=".xlsx,.xls,.csv" onChange={event => event.target.files?.[0] && readFile(event.target.files[0])} /><FileSpreadsheet size={21} /><strong>Escolher planilha</strong><span>ou arraste aqui · até 20.000 linhas</span></label><div className="upload-divider"><span>ou cole nomes</span></div><textarea value={pasted} onChange={event => setPasted(event.target.value)} placeholder="Um nome por linha" rows={4} /><Button variant="outline" onClick={preparePasted} disabled={!pasted.trim()}><ClipboardList size={16} /> Preparar lista</Button></section><aside className="panel import-side"><p className="eyebrow">MAPEAMENTO EDITÁVEL</p><h2>Confira antes de importar</h2><p>Escolha manualmente a coluna correspondente a cada campo. O endereço original é preservado.</p><div className="mapping-preview"><span><Check size={14} /> Prévia real das primeiras linhas</span><span><Check size={14} /> Telefones incompletos preservados</span><span><Check size={14} /> Duplicidades como sinal</span></div></aside></div> : <section className="panel"><div className="preview-heading"><div><div className="file-chip"><FileSpreadsheet size={15} /> {fileName}</div><h2>Prévia da importação particular</h2><p>{formatNumber(rows.length)} linhas · {headers.length} colunas</p></div><button className="icon-button" onClick={() => setShowPreview(false)}><X size={18} /></button></div><div className="settings-grid"><label><span>Categoria padrão</span><select value={category} onChange={event => setCategory(event.target.value)}><option>Produtor rural</option><option>Comprador de grãos</option><option>Transportadora</option><option>Confinamento</option></select></label><label><span>DDD para revisão (opcional)</span><input value={defaultAreaCode} onChange={event => setDefaultAreaCode(event.target.value.replace(/\D/g, "").slice(0, 2))} placeholder="Ex.: 64" /><small>Aplicado somente na confirmação e prévia desta importação.</small></label></div><div className="editable-mapping"><p className="eyebrow">MAPEAMENTO EDITÁVEL</p>{importFields.map(field => <label key={field}><span>{field}</span><select value={mapping[field] || ""} onChange={event => setMapping({ ...mapping, [field]: event.target.value || null })}><option value="">Não importar</option>{headers.map(header => <option key={`${field}-${header}`} value={header}>{header}</option>)}</select></label>)}</div><div className="preview-table-wrap"><table><thead><tr><th>Nome</th><th>Telefone</th><th>Cidade/UF</th><th>Categoria</th><th>Produto</th><th>Situação</th></tr></thead><tbody>{preview.map((item, index) => <tr key={index}><td><strong>{item.name}</strong></td><td>{item.phones[0]?.original || "—"}</td><td>{item.city || "—"}{item.state ? `, ${item.state}` : ""}</td><td>{item.category}</td><td>{item.products || "—"}</td><td>{item.pendingReasons.length ? <StatusPill tone="amber">{item.pendingReasons[0]}</StatusPill> : <StatusPill tone="green">Pronto</StatusPill>}</td></tr>)}</tbody></table></div><div className="preview-footer"><span><ShieldCheck size={15} /> Nenhuma informação enviada a serviço externo.</span><Button onClick={confirm} disabled={startImport.isPending}>{startImport.isPending ? <Loader2 className="spin" size={16} /> : <CloudUpload size={16} />} Confirmar importação</Button></div></section>}</div>;
}

function TemplatesView({ demo }: { demo: boolean }) {
  const templates = trpc.templates.list.useQuery(undefined, { enabled: !demo, retry: false }); const fallback = [{ id: 1, name: "Primeiro contato", body: "Olá, {primeiro_nome}! Podemos conversar?", purpose: "primeiro contato", isDefault: true }]; const items: any[] = demo ? fallback : templates.data || []; const [selectedId, setSelectedId] = useState<number | null>(demo ? 1 : null); const [editing, setEditing] = useState(false); const [dirty, setDirty] = useState(false); const [form, setForm] = useState({ name: "", body: "", purpose: "geral" }); const current = items.find(item => item.id === selectedId);
  useEffect(() => { if (!editing && !dirty && !current && items.length) setSelectedId(items[0].id); }, [items, current, editing, dirty]); useEffect(() => { if (!dirty) setForm({ name: current?.name || "", body: current?.body || "", purpose: current?.purpose || "geral" }); }, [current, dirty]);
  const create = trpc.templates.create.useMutation({ onSuccess: () => { templates.refetch(); setEditing(false); setDirty(false); toast.success("Modelo criado."); } }); const update = trpc.templates.update.useMutation({ onSuccess: () => { templates.refetch(); setEditing(false); setDirty(false); toast.success("Modelo atualizado."); } }); const archive = trpc.templates.archive.useMutation({ onSuccess: () => { templates.refetch(); setSelectedId(null); setDirty(false); toast.success("Modelo arquivado."); } }); const setDefault = trpc.templates.setDefault.useMutation({ onSuccess: () => { templates.refetch(); toast.success("Modelo padrão atualizado."); } }); const duplicate = trpc.templates.duplicate.useMutation({ onSuccess: () => { templates.refetch(); toast.success("Modelo duplicado."); } });
  const selectItem = (id: number) => { setSelectedId(id); setEditing(false); setDirty(false); }; const updateForm = (next: typeof form) => { setForm(next); setDirty(true); }; const save = () => { if (demo) return toast.info("Modelos da demonstração não são salvos."); if (!form.name || !form.body) return toast.error("Informe nome e mensagem."); if (current) update.mutate({ templateId: current.id, ...form }); else create.mutate(form); };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">MENSAGENS PRIVADAS</p><h1>Modelos de mensagem</h1><p>Escolha, revise e reutilize mensagens sem deixar variáveis soltas.</p></div><Button onClick={() => { setSelectedId(null); setForm({ name: "", body: "", purpose: "geral" }); setDirty(false); setEditing(true); }}><Plus size={16} /> Novo modelo</Button></div><div className="template-layout"><section className="panel template-list"><div className="panel-heading"><div><p className="eyebrow">SEUS MODELOS</p><h2>Mensagens salvas</h2></div></div>{items.map(item => <button className={`template-item ${item.id === selectedId ? "selected" : ""}`} key={item.id} onClick={() => selectItem(item.id)}><span className="template-icon"><MessageCircle size={17} /></span><span><strong>{item.name}</strong><small>{item.purpose || "geral"}{item.isDefault ? " · padrão" : ""}</small></span><ChevronRight size={15} /></button>)}{!items.length && <EmptyState icon={MessageCircle} title="Nenhum modelo salvo" description="Crie uma mensagem para usar na próxima conversa." />}</section><section className="panel template-editor">{editing || current ? <><div className="editor-heading"><div><span className="file-chip">{current?.isDefault ? "PADRÃO" : "MODELO"}</span><h2>{current?.name || "Novo modelo"}</h2></div><div className="title-actions">{current && <button className="icon-button" onClick={() => demo ? toast.info("A demonstração não altera modelos.") : setEditing(value => !value)}><Pencil size={17} /></button>}{current && <button className="icon-button" onClick={() => demo ? toast.info("A demonstração não altera modelos.") : archive.mutate({ templateId: current.id })}><Archive size={17} /></button>}</div></div><label className="editor-label">Nome<input value={form.name} onChange={event => updateForm({ ...form, name: event.target.value })} readOnly={!editing && Boolean(current)} /></label><label className="editor-label">Mensagem<textarea value={form.body} onChange={event => updateForm({ ...form, body: event.target.value })} readOnly={!editing && Boolean(current)} rows={7} /></label><div className="variable-list"><span>Variáveis</span>{["{nome}", "{primeiro_nome}", "{empresa}", "{cidade}", "{estado}", "{produto}", "{nome_usuario}", "{nome_organizacao}"].map(variable => <button key={variable} onClick={() => updateForm({ ...form, body: `${form.body} ${variable}` })}>{variable}</button>)}</div><div className="message-preview"><p className="eyebrow">PRÉVIA</p><p>{interpolateMessage(form.body, { primeiro_nome: "Marcos", nome_usuario: "Ana", nome_organizacao: "Agro Norte", produto: "soja", cidade: "Rio Verde", estado: "GO" })}</p></div><div className="preview-footer">{current && !editing ? <><Button variant="outline" onClick={() => demo ? toast.info("A demonstração não altera modelos.") : setDefault.mutate({ templateId: current.id })}><Star size={15} /> Tornar padrão</Button><Button variant="outline" onClick={() => demo ? toast.info("A demonstração não altera modelos.") : duplicate.mutate({ templateId: current.id })}>Duplicar</Button></> : <Button onClick={save} disabled={create.isPending || update.isPending}>Salvar modelo</Button>}<span>O texto será revisado antes da abertura.</span></div></> : <EmptyState icon={MessageCircle} title="Selecione ou crie um modelo" description="A mensagem escolhida será aplicada às variáveis do contato." />}</section></div></div>;
}

function CrmView({ demo }: { demo: boolean }) {
  const tasksQuery = trpc.tasks.list.useQuery({ includeCompleted: true }, { enabled: !demo, retry: false });
  const candidates = trpc.tasks.candidates.useQuery(undefined, { enabled: !demo, retry: false });
  const [showForm, setShowForm] = useState(false); const [editing, setEditing] = useState<any>(null);
  const [form, setForm] = useState({ title: "", dueAt: "", contactId: "", catalogContactId: "" });
  const create = trpc.tasks.create.useMutation({ onSuccess: () => { tasksQuery.refetch(); setForm({ title: "", dueAt: "", contactId: "", catalogContactId: "" }); setShowForm(false); toast.success("Tarefa criada."); }, onError: error => toast.error(error.message) });
  const update = trpc.tasks.update.useMutation({ onSuccess: () => { tasksQuery.refetch(); setForm({ title: "", dueAt: "", contactId: "", catalogContactId: "" }); setShowForm(false); setEditing(null); toast.success("Tarefa atualizada."); }, onError: error => toast.error(error.message) });
  const complete = trpc.tasks.complete.useMutation({ onSuccess: () => tasksQuery.refetch(), onError: error => toast.error(error.message) });
  const tasks: any[] = demo ? [] : tasksQuery.data || [];
  const openNew = () => { setEditing(null); setForm({ title: "", dueAt: "", contactId: "", catalogContactId: "" }); setShowForm(true); };
  const openEdit = (task: any) => { setEditing(task); setForm({ title: task.title, dueAt: task.dueAt ? new Date(task.dueAt).toISOString().slice(0, 16) : "", contactId: task.contactId ? String(task.contactId) : "", catalogContactId: task.catalogContactId ? String(task.catalogContactId) : "" }); setShowForm(true); };
  const save = () => { if (!form.title.trim()) return toast.error("Informe o título."); if (form.contactId && form.catalogContactId) return toast.error("Escolha um único contato."); const payload = { title: form.title, dueAt: form.dueAt ? new Date(form.dueAt).toISOString() : null, contactId: form.contactId ? Number(form.contactId) : null, catalogContactId: form.catalogContactId ? Number(form.catalogContactId) : null }; if (editing) update.mutate({ taskId: editing.id, ...payload }); else create.mutate(payload); };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">ACOMPANHAMENTO PRIVADO</p><h1>Tarefas e CRM</h1><p>Organize o próximo contato particular ou central sem misturar dados entre organizações.</p></div><Button onClick={() => demo ? toast.info("A demonstração não cria tarefas.") : openNew()}><Plus size={16} /> Nova tarefa</Button></div>{showForm && <section className="panel contact-form-panel"><div className="panel-heading"><h2>{editing ? "Editar tarefa" : "Nova tarefa"}</h2><button className="icon-button" onClick={() => setShowForm(false)}><X size={18} /></button></div><div className="form-grid"><label><span>Título</span><input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Ex.: retornar sobre frete" /></label><label><span>Prazo</span><input type="datetime-local" value={form.dueAt} onChange={event => setForm({ ...form, dueAt: event.target.value })} /></label><label><span>Contato particular</span><select value={form.contactId} onChange={event => setForm({ ...form, contactId: event.target.value, catalogContactId: "" })}><option value="">Sem vínculo particular</option>{(candidates.data?.private || []).map((contact: any) => <option key={contact.id} value={contact.id}>{contact.name}{contact.company ? ` · ${contact.company}` : ""}</option>)}</select></label><label><span>Contato da Base AGROLINK</span><select value={form.catalogContactId} onChange={event => setForm({ ...form, catalogContactId: event.target.value, contactId: "" })}><option value="">Sem vínculo central</option>{(candidates.data?.catalog || []).map((contact: any) => <option key={contact.id} value={contact.id}>{contact.name}{contact.company ? ` · ${contact.company}` : ""}</option>)}</select></label></div><div className="preview-footer"><span>{(candidates.data?.private?.length || 0) + (candidates.data?.catalog?.length || 0)} contatos disponíveis para vínculo</span><Button onClick={save} disabled={create.isPending || update.isPending}>{editing ? "Salvar tarefa" : "Criar tarefa"}</Button></div></section>}<section className="panel tasks-panel"><div className="panel-heading"><div><p className="eyebrow">AGENDA</p><h2>Próximas tarefas</h2></div></div><div className="task-list">{tasks.length ? tasks.map(task => <div className={`task-row ${task.status === "done" ? "completed" : ""}`} key={task.id}><button className="task-check" onClick={() => task.status === "pending" && complete.mutate({ taskId: task.id, status: "done" })}>{task.status === "done" ? <Check size={13} /> : null}</button><span><strong>{task.title}</strong><small>{formatDate(task.dueAt)} · {task.catalogContactId ? "Base AGROLINK" : task.contactId ? "Contato particular" : "Sem vínculo"} · {task.status === "done" ? "concluída" : "pendente"}</small></span><button className="icon-button" onClick={() => openEdit(task)} aria-label="Editar tarefa"><Pencil size={16} /></button></div>) : <EmptyState icon={ClipboardList} title="Nenhuma tarefa" description={demo ? "A demonstração não contém tarefas reais." : "Crie uma tarefa para acompanhar o próximo contato."} />}</div></section><section className="panel privacy-note"><ShieldCheck size={20} /><div><strong>Seu acompanhamento é privado</strong><p>Notas, tarefas e atividades ficam na sua organização, inclusive quando o contato veio do catálogo central.</p></div></section></div>;
}

function SettingsView({ demo }: { demo: boolean }) {
  const organization = trpc.organization.current.useQuery(undefined, { enabled: !demo, retry: false });
  const members = trpc.organization.members.useQuery(undefined, { enabled: !demo, retry: false });
  const backup = trpc.organization.backup.useQuery(undefined, { enabled: false, retry: false });
  const update = trpc.organization.updateSettings.useMutation({ onSuccess: () => { organization.refetch(); toast.success("Configurações salvas."); }, onError: error => toast.error(error.message) });
  const updateMember = trpc.organization.updateMember.useMutation({ onSuccess: () => { members.refetch(); toast.success("Membro atualizado."); }, onError: error => toast.error(error.message) });
  const restore = trpc.organization.restore.useMutation({ onSuccess: result => toast.success(`${result.restoredContacts} contato(s) e ${result.restoredTemplates} modelo(s) restaurado(s).`), onError: error => toast.error(error.message) });
  const org = organization.data?.organization; const member = organization.data?.member;
  const [form, setForm] = useState({ name: "", defaultAreaCode: "", defaultMessage: "Olá, {primeiro_nome}! Podemos conversar?", usePhonesAsWhatsapp: true, openWhatsappDirectly: false });
  useEffect(() => { if (org) setForm({ name: org.name || "", defaultAreaCode: org.defaultAreaCode || "", defaultMessage: org.defaultMessage || "Olá, {primeiro_nome}! Podemos conversar?", usePhonesAsWhatsapp: org.usePhonesAsWhatsapp ?? true, openWhatsappDirectly: org.openWhatsappDirectly ?? false }); }, [org]);
  const downloadBackup = async () => { const result = await backup.refetch(); if (!result.data) return; const blob = new Blob([JSON.stringify(result.data, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `agrolink-backup-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); URL.revokeObjectURL(url); toast.success("Backup exportado."); };
  const readBackup = async (file: File) => { try { const text = await file.text(); JSON.parse(text); if (!window.confirm("A restauração adicionará registros ao espaço atual e não apaga dados existentes. Continuar?")) return; restore.mutate({ backup: text }); } catch { toast.error("Arquivo de backup inválido."); } };
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">CONTROLE DA ORGANIZAÇÃO</p><h1>Configurações</h1><p>Preferências, equipe e continuidade operacional da sua organização.</p></div></div><section className="panel settings-card"><div className="settings-card-heading"><div><p className="eyebrow">DADOS GERAIS</p><h2>Perfil e WhatsApp</h2></div><Button variant="outline" size="sm" onClick={() => demo ? toast.info("A demonstração não salva configurações.") : update.mutate(form)}><Check size={15} /> Salvar alterações</Button></div><div className="form-grid"><label><span>Nome da organização</span><input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></label><label><span>País padrão</span><select defaultValue="BR"><option value="BR">Brasil (+55)</option></select></label><label><span>DDD padrão <em>opcional</em></span><input value={form.defaultAreaCode} onChange={event => setForm({ ...form, defaultAreaCode: event.target.value })} placeholder="Ex.: 64" /></label><label><span>Mensagem padrão</span><textarea value={form.defaultMessage} onChange={event => setForm({ ...form, defaultMessage: event.target.value })} rows={3} /></label></div><div className="setting-divider" /><div className="setting-row"><div><strong>Usar telefones como WhatsApp</strong><small>Define a intenção do link, mas não confirma conta ativa.</small></div><button className={`toggle ${form.usePhonesAsWhatsapp ? "on" : ""}`} onClick={() => setForm({ ...form, usePhonesAsWhatsapp: !form.usePhonesAsWhatsapp })}><span /></button></div></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">EQUIPE</p><h2>Membros e permissões</h2></div><StatusPill tone={member?.role === "owner" ? "green" : "blue"}>{member?.role || "carregando"}</StatusPill></div>{members.data?.length ? <div className="table-wrap"><table><thead><tr><th>Usuário</th><th>Papel</th><th>Status</th><th>Ação</th></tr></thead><tbody>{members.data.map((row: any) => <tr key={row.member.id}><td><strong>{row.user.name || "Sem nome"}</strong><small>{row.user.email || "E-mail não informado"}</small></td><td><select value={row.member.role} disabled={member?.role !== "owner" && member?.role !== "admin"} onChange={event => updateMember.mutate({ memberId: row.member.id, role: event.target.value as "owner" | "admin" | "operator" })}><option value="owner">Proprietário</option><option value="admin">Administrador</option><option value="operator">Operador</option></select></td><td><StatusPill tone={row.member.status === "active" ? "green" : "amber"}>{row.member.status}</StatusPill></td><td><button className="filter-button" disabled={member?.role !== "owner" && member?.role !== "admin"} onClick={() => updateMember.mutate({ memberId: row.member.id, status: row.member.status === "suspended" ? "active" : "suspended" })}>{row.member.status === "suspended" ? "Reativar" : "Suspender"}</button></td></tr>)}</tbody></table></div> : <EmptyState icon={Users} title="Nenhum membro carregado" description="A equipe aparecerá quando houver membros na organização." />}</section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">CONTINUIDADE E PRIVACIDADE</p><h2>Backup e restauração</h2></div></div><p>O backup contém contatos particulares, telefones, modelos e membros da organização. A restauração é aditiva: não apaga registros existentes e exige confirmação.</p><div className="title-actions"><Button variant="outline" onClick={() => demo ? toast.info("A demonstração não exporta dados.") : downloadBackup()} disabled={backup.isFetching}><Download size={16} /> Exportar backup</Button><label className="filter-button"><FileSpreadsheet size={15} /> Restaurar backup<input type="file" accept="application/json,.json" hidden onChange={event => event.target.files?.[0] && readBackup(event.target.files[0])} /></label></div></section><div className="pending-integration"><div className="pending-icon"><BarChart3 size={18} /></div><div><strong>Cobrança ainda não integrada</strong><p>Checkout, renovação e webhooks Stripe continuam pendentes de configuração externa; nenhum pagamento é simulado.</p></div><StatusPill tone="amber">Pendente</StatusPill></div></div>;
}

function AdminCatalogView({ demo }: { demo: boolean }) {
  const [rows, setRows] = useState<RawRow[]>([]); const [headers, setHeaders] = useState<string[]>([]); const [mapping, setMapping] = useState<Record<string, string | null>>({}); const [fileName, setFileName] = useState(""); const [sourceType, setSourceType] = useState<"xlsx" | "csv">("xlsx"); const [category, setCategory] = useState("Produtor rural"); const [defaultAreaCode, setDefaultAreaCode] = useState(""); const [preview, setPreview] = useState(false); const [selected, setSelected] = useState<number[]>([]); const [page, setPage] = useState(0); const [manual, setManual] = useState({ name: "", company: "", phone: "" }); const [status, setStatus] = useState<"pending" | "reviewed" | "published" | "inactive">("pending");
  const adminOverview = trpc.admin.overview.useQuery(undefined, { enabled: !demo, retry: false }); const users = trpc.admin.users.useQuery(undefined, { enabled: !demo, retry: false }); const manualUser = useState({ name: "", email: "", organizationId: "", role: "operator" as "owner" | "admin" | "operator" }); const createUser = trpc.admin.createUser.useMutation({ onSuccess: () => { users.refetch(); manualUser[1]({ name: "", email: "", organizationId: "", role: "operator" }); toast.success("Usuário cadastrado como convite pendente."); }, onError: error => toast.error(error.message) }); const updateUser = trpc.admin.updateUser.useMutation({ onSuccess: () => { users.refetch(); toast.success("Acesso do usuário atualizado."); }, onError: error => toast.error(error.message) }); const updateSubscription = trpc.admin.updateSubscription.useMutation({ onSuccess: () => { accesses.refetch(); toast.success("Assinatura atualizada."); }, onError: error => toast.error(error.message) }); const imports = trpc.admin.catalogImports.useQuery(undefined, { enabled: !demo, retry: false }); const contacts = trpc.admin.catalogContacts.useQuery({ status, limit: 50, offset: page * 50 }, { enabled: !demo, retry: false }); const accesses = trpc.admin.accessOrganizations.useQuery(undefined, { enabled: !demo, retry: false }); const audit = trpc.admin.audit.useQuery(undefined, { enabled: !demo, retry: false });
  const createManual = trpc.admin.createCatalogContact.useMutation({ onSuccess: () => { contacts.refetch(); setManual({ name: "", company: "", phone: "" }); toast.success("Contato central criado para conferência."); }, onError: error => toast.error(error.message) }); const updateCatalog = trpc.admin.updateCatalog.useMutation({ onSuccess: () => { contacts.refetch(); toast.success("Contato central atualizado e devolvido à revisão."); }, onError: error => toast.error(error.message) }); const setCatalogStatus = trpc.admin.setCatalogStatus.useMutation({ onSuccess: () => { contacts.refetch(); toast.success("Status do contato atualizado."); }, onError: error => toast.error(error.message) }); const importMutation = trpc.admin.importCatalog.useMutation({ onSuccess: () => { imports.refetch(); contacts.refetch(); setPreview(false); toast.success("Lote central processado para conferência."); }, onError: error => toast.error(error.message) }); const publishSelected = trpc.admin.publishCatalogContacts.useMutation({ onSuccess: result => { contacts.refetch(); imports.refetch(); setSelected([]); toast.success(`${result.published} contato(s) publicado(s); ${result.skipped} ignorado(s).`); }, onError: error => toast.error(error.message) }); const approve = trpc.admin.approveCatalog.useMutation({ onSuccess: result => { contacts.refetch(); imports.refetch(); setSelected([]); toast.success(`${result.approved} registro(s) aprovado(s); ${result.blocked.length} bloqueado(s).`); }, onError: error => toast.error(error.message) }); const publish = trpc.admin.publishCatalogBatch.useMutation({ onSuccess: result => { contacts.refetch(); imports.refetch(); toast.success(`${result.published} publicado(s); ${result.pending} pendente(s).`); }, onError: error => toast.error(error.message) }); const setAccess = trpc.admin.setCatalogAccess.useMutation({ onSuccess: () => { accesses.refetch(); toast.success("Acesso atualizado com validade e auditoria."); }, onError: error => toast.error(error.message) });
  const readFile = async (file: File) => { setFileName(file.name); setSourceType(file.name.toLowerCase().endsWith(".csv") ? "csv" : "xlsx"); const workbook = XLSX.read(await file.arrayBuffer(), { type: "array", raw: false }); const sheet = workbook.Sheets[workbook.SheetNames[0]]; const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" }) as unknown[][]; const first = (matrix[0] || []).map(item => String(item)); setHeaders(first); setRows(matrix.slice(1).filter(row => row.some(value => String(value).trim())).map(row => Object.fromEntries(first.map((header, index) => [header, row[index] ?? ""])))); setMapping(detectMapping(first)); setPreview(true); };
  const previewRows = useMemo(() => rows.slice(0, 5).map(row => mapRow(row, mapping, { category, defaultAreaCode: defaultAreaCode || undefined, usePhonesAsWhatsapp: true })), [rows, mapping, category, defaultAreaCode]);
  return <div className="view-stack"><div className="page-title-row"><div><p className="eyebrow">ADMINISTRAÇÃO DA PLATAFORMA</p><h1>Base central</h1><p>Importe, corrija, aprove individualmente e publique somente registros conferidos.</p><div className="tag-line">Conta atual: {adminOverview.data?.user?.email || adminOverview.data?.user?.name || "administrador"} · papel {adminOverview.data?.user?.role || "admin"}</div></div></div><section className="panel"><div className="panel-heading"><div><p className="eyebrow">GESTÃO DE USUÁRIOS</p><h2>Usuários e acessos</h2><p>Cadastre quem comprou fora da API e ative, bloqueie ou altere o papel de login.</p></div></div><div className="settings-grid"><input placeholder="Nome completo" value={manualUser[0].name} onChange={event => manualUser[1]({ ...manualUser[0], name: event.target.value })} /><input type="email" placeholder="E-mail usado no login" value={manualUser[0].email} onChange={event => manualUser[1]({ ...manualUser[0], email: event.target.value })} /><select value={manualUser[0].organizationId} onChange={event => manualUser[1]({ ...manualUser[0], organizationId: event.target.value })}><option value="">Organização do acesso</option>{accesses.data?.map((item: any) => <option key={item.organization.id} value={item.organization.id}>{item.organization.name}</option>)}</select><select value={manualUser[0].role} onChange={event => manualUser[1]({ ...manualUser[0], role: event.target.value as "owner" | "admin" | "operator" })}><option value="operator">Operador</option><option value="admin">Administrador</option><option value="owner">Proprietário</option></select><Button onClick={() => manualUser[0].name && manualUser[0].email && manualUser[0].organizationId ? createUser.mutate({ name: manualUser[0].name, email: manualUser[0].email, organizationId: Number(manualUser[0].organizationId), role: manualUser[0].role }) : toast.error("Informe nome, e-mail e organização.")}>Cadastrar usuário</Button></div><div className="table-wrap"><table><thead><tr><th>Usuário</th><th>Organização / papel</th><th>Login</th><th>Controle</th></tr></thead><tbody>{users.data?.map((row: any) => row.organizations.map((entry: any) => <tr key={`${row.user.id}-${entry.membership.id}`}><td><strong>{row.user.name || "Sem nome"}</strong><small>{row.user.email || "Sem e-mail"}</small></td><td>{entry.organization.name}<br /><StatusPill tone="blue">{entry.membership.role}</StatusPill></td><td><StatusPill tone={row.user.accessStatus === "active" ? "green" : row.user.accessStatus === "blocked" ? "amber" : "blue"}>{row.user.accessStatus}</StatusPill><small>{row.user.loginMethod === "manual" ? "aguarda primeiro login" : "login vinculado"}</small></td><td><div className="title-actions"><button className="filter-button" onClick={() => updateUser.mutate({ userId: row.user.id, accessStatus: row.user.accessStatus === "blocked" ? "active" : "blocked" })}>{row.user.accessStatus === "blocked" ? "Ativar login" : "Bloquear login"}</button><select value={entry.membership.role} onChange={event => updateUser.mutate({ userId: row.user.id, memberId: entry.membership.id, role: event.target.value as "owner" | "admin" | "operator" })}><option value="operator">Operador</option><option value="admin">Administrador</option><option value="owner">Proprietário</option></select></div></td></tr>))}</tbody></table></div></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">CADASTRO MANUAL</p><h2>Novo contato central</h2></div></div><div className="settings-grid"><input placeholder="Nome obrigatório" value={manual.name} onChange={event => setManual({ ...manual, name: event.target.value })} /><input placeholder="Empresa ou propriedade" value={manual.company} onChange={event => setManual({ ...manual, company: event.target.value })} /><input placeholder="Telefone original" value={manual.phone} onChange={event => setManual({ ...manual, phone: event.target.value })} /><Button onClick={() => manual.name.trim() ? createManual.mutate({ name: manual.name, company: manual.company || null, phones: manual.phone ? [{ original: manual.phone, isWhatsapp: true }] : [] }) : toast.error("Informe o nome.")}>Cadastrar para revisão</Button></div></section><section className="panel admin-panel"><div className="upload-symbol"><CloudUpload size={22} /></div><h2>Importar base administrada</h2><p>O lote fica fora do catálogo até terminar, ser conferido e ter registros aprovados.</p><label className="upload-drop"><input type="file" accept=".xlsx,.xls,.csv" onChange={event => event.target.files?.[0] && readFile(event.target.files[0])} /><FileSpreadsheet size={21} /><strong>Escolher XLSX ou CSV</strong><span>prévia e mapeamento antes do processamento</span></label>{preview && <><div className="editable-mapping">{importFields.map(field => <label key={field}><span>{field}</span><select value={mapping[field] || ""} onChange={event => setMapping({ ...mapping, [field]: event.target.value || null })}><option value="">Não importar</option>{headers.map(header => <option key={`${field}-${header}`} value={header}>{header}</option>)}</select></label>)}</div><div className="preview-table-wrap"><table><thead><tr><th>Nome</th><th>Telefone</th><th>Cidade/UF</th><th>Categoria</th><th>Produto</th></tr></thead><tbody>{previewRows.map((item, index) => <tr key={index}><td>{item.name}</td><td>{item.phones[0]?.original || "—"}</td><td>{item.city || "—"}{item.state ? `, ${item.state}` : ""}</td><td>{item.category}</td><td>{item.products || "—"}</td></tr>)}</tbody></table></div><div className="settings-grid"><label><span>Categoria padrão</span><select value={category} onChange={event => setCategory(event.target.value)}><option>Produtor rural</option><option>Comprador de grãos</option><option>Confinamento</option><option>Transportadora</option></select></label><label><span>DDD para revisão (opcional)</span><input value={defaultAreaCode} onChange={event => setDefaultAreaCode(event.target.value.replace(/\D/g, "").slice(0, 2))} placeholder="Ex.: 64" /><small>Aplicado somente neste lote, com prévia.</small></label><label><span>Arquivo</span><small>{fileName} · {formatNumber(rows.length)} linhas</small></label></div><div className="preview-footer"><span>Registros problemáticos continuam pendentes.</span><Button onClick={() => demo ? toast.info("Demonstração não altera a base central.") : importMutation.mutate({ fileName, sourceType, rows, mapping, category, defaultAreaCode: defaultAreaCode || undefined })} disabled={importMutation.isPending}>Processar lote</Button></div></>}</section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">REGISTROS CENTRAIS</p><h2>Conferência e aprovação</h2></div><div className="title-actions"><select value={status} onChange={event => { setStatus(event.target.value as typeof status); setPage(0); setSelected([]); }}><option value="pending">Pendentes</option><option value="reviewed">Aprovados</option><option value="published">Publicados</option><option value="inactive">Inativos</option></select>{selected.length > 0 && (status === "reviewed" ? <Button size="sm" onClick={() => publishSelected.mutate({ catalogContactIds: selected })}>Publicar selecionados ({selected.length})</Button> : <Button size="sm" onClick={() => approve.mutate({ catalogContactIds: selected })}>Aprovar selecionados ({selected.length})</Button>)}</div></div>{contacts.data?.rows?.length ? <div className="table-wrap"><table><thead><tr><th><input type="checkbox" checked={contacts.data.rows.length > 0 && contacts.data.rows.every((row: any) => selected.includes(row.id))} onChange={event => setSelected(event.target.checked ? contacts.data.rows.map((row: any) => row.id) : [])} /></th><th>Contato</th><th>Localização</th><th>Telefones</th><th>Status</th></tr></thead><tbody>{contacts.data.rows.map((contact: any) => <tr key={contact.id}><td><input type="checkbox" checked={selected.includes(contact.id)} onChange={() => setSelected(current => current.includes(contact.id) ? current.filter(id => id !== contact.id) : [...current, contact.id])} /></td><td><strong>{contact.name}</strong><small>{contact.company || "—"}</small></td><td>{contact.city || "—"}{contact.state ? `, ${contact.state}` : ""}</td><td>{contact.phones?.map((phone: any) => <span className="tag-line" key={phone.id}>{phone.original} · {phone.validationStatus}</span>)}</td><td><StatusPill tone={contact.reviewStatus === "published" ? "green" : contact.reviewStatus === "reviewed" ? "blue" : "amber"}>{contact.reviewStatus}</StatusPill><div className="tag-line"><button className="icon-button" onClick={() => { const name = window.prompt("Nome", contact.name); if (name === null) return; const company = window.prompt("Empresa ou propriedade", contact.company || ""); const city = window.prompt("Cidade", contact.city || ""); const state = window.prompt("UF", contact.state || ""); const products = window.prompt("Produtos/atuação", contact.products || ""); const email = window.prompt("E-mail", contact.email || ""); const addressOriginal = window.prompt("Endereço original", contact.addressOriginal || ""); const categories = window.prompt("Categorias (separadas por vírgula)", (contact.categories || []).join(", ")); const tags = window.prompt("Etiquetas (separadas por vírgula)", (contact.tags || []).join(", ")); const phone = window.prompt("Telefone principal", contact.phones?.[0]?.original || ""); updateCatalog.mutate({ catalogContactId: contact.id, name: name.trim(), company: company || null, city: city || null, state: state || null, products: products || null, email: email || null, addressOriginal: addressOriginal || null, categories: (categories || "").split(",").map(item => item.trim()).filter(Boolean), tags: (tags || "").split(",").map(item => item.trim()).filter(Boolean), phones: phone ? [{ original: phone, isWhatsapp: true, isPreferred: true }] : [] }); }} title="Editar contato completo"><Pencil size={14} /></button>{contact.reviewStatus !== "inactive" && <button className="icon-button" onClick={() => setCatalogStatus.mutate({ catalogContactId: contact.id, status: "inactive" })} title="Inativar">Inativar</button>}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={ShieldCheck} title="Nenhum registro neste status" description="Importe um lote ou altere o filtro de conferência." />}</section><div className="table-footer"><span>{formatNumber(contacts.data?.total || 0)} registros · página {page + 1}</span><div><button className="pager-button" disabled={page === 0} onClick={() => { setPage(page - 1); setSelected([]); }}>Anterior</button><button className="pager-button" disabled={!contacts.data || (page + 1) * 50 >= contacts.data.total} onClick={() => { setPage(page + 1); setSelected([]); }}>Próxima</button></div></div><section className="content-grid dashboard-grid"><section className="panel attention-panel"><div className="panel-heading"><div><p className="eyebrow">LOTES</p><h2>Publicação</h2></div></div><div className="attention-list">{imports.data?.length ? imports.data.slice(0, 8).map((item: any) => <div className="admin-import-row" key={item.id}><span><strong>{item.fileName || `Lote ${item.id}`}</strong><small>{formatNumber(item.createdContacts)} criados · {formatNumber(item.reviewRows)} pendentes · {formatNumber(item.publishedRows || 0)} publicados</small></span><button className="filter-button" disabled={item.status !== "completed" || publish.isPending} onClick={() => publish.mutate({ batchId: item.id })}>{item.status === "completed" ? "Publicar aprovados" : item.status}</button></div>) : <EmptyState icon={FileSpreadsheet} title="Sem importações" description="O histórico administrativo aparecerá aqui." />}</div></section><section className="panel attention-panel"><div className="panel-heading"><div><p className="eyebrow">ACESSOS</p><h2>Liberação manual com validade</h2></div></div><div className="attention-list">{accesses.data?.map((item: any) => <div className="admin-import-row" key={item.organization.id}><span><strong>{item.organization.name}</strong><small>Plano {item.subscription?.plan || "não definido"} · {item.subscription?.status || "sem assinatura"} · {item.grant ? `liberação até ${formatDate(item.grant.validUntil)}` : "sem liberação manual"}</small></span><div className="title-actions"><select value={item.subscription?.plan || "essential"} onChange={event => updateSubscription.mutate({ organizationId: item.organization.id, plan: event.target.value as "essential" | "professional" | "enterprise", catalogIncluded: true })}><option value="essential">Essencial</option><option value="professional">Profissional</option><option value="enterprise">Empresarial</option></select><button className="filter-button" onClick={() => item.grant ? setAccess.mutate({ organizationId: item.organization.id, action: "revoke", reason: "Revogado pela administração" }) : setAccess.mutate({ organizationId: item.organization.id, action: "grant", validUntil: new Date(Date.now() + 30 * 86400000).toISOString(), reason: "Liberação manual temporária" })}>{item.grant ? "Revogar" : "Liberar 30 dias"}</button></div></div>)}</div></section></section><section className="panel privacy-note"><ShieldCheck size={20} /><div><strong>Histórico administrativo</strong><p>{audit.data?.length || 0} eventos registrados. Favoritos, notas e tarefas das organizações não são apagados quando um registro central é corrigido.</p></div></section></div>;
}

export default function AppDashboard({ demo = false }: { demo?: boolean }) {
  const { user, loading, logout, isAuthenticated } = useAuth(); const { theme, toggleTheme } = useTheme(); const [, setLocation] = useLocation(); const organization = trpc.organization.current.useQuery(undefined, { enabled: !demo && isAuthenticated, retry: false }); const canManageContacts = demo || organization.data?.member?.role === "owner" || organization.data?.member?.role === "admin"; const [view, setView] = useState("overview"); const [mobileOpen, setMobileOpen] = useState(false);
  if (!demo && loading) return <div className="app-loading"><Loader2 className="spin" size={24} /><span>Carregando seu espaço de trabalho…</span></div>;
  if (!demo && !isAuthenticated) return <div className="auth-gate"><Logo /><div className="auth-card"><div className="auth-icon"><ShieldCheck size={22} /></div><h1>Entre para acessar o AGROLINK</h1><p>Use sua conta para consultar a base liberada e cuidar dos contatos da sua organização.</p><div className="auth-actions"><Button onClick={() => setLocation("/login")}>Entrar</Button><Button variant="outline" onClick={() => setLocation("/")}>Voltar para a página inicial</Button></div></div></div>;
  const navItems = [{ id: "overview", label: "Visão geral", icon: LayoutDashboard }, { id: "catalog", label: "Base AGROLINK", icon: Database }, { id: "private", label: "Meus contatos", icon: ContactRound }, ...(canManageContacts ? [{ id: "imports", label: "Importar meus contatos", icon: CloudUpload }] : []), { id: "crm", label: "Tarefas e CRM", icon: ClipboardList }, { id: "templates", label: "Modelos de mensagem", icon: MessageCircle }, { id: "settings", label: "Configurações", icon: Settings }, ...(user?.role === "admin" && !demo ? [{ id: "admin", label: "Administração da base", icon: ShieldCheck }] : [])]; const activeLabel = navItems.find(item => item.id === view)?.label || "Visão geral"; const switchView = (id: string) => { setView(id); setMobileOpen(false); };
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? "open" : ""}`}><div className="sidebar-top"><Logo /><button className="mobile-close" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="workspace-switcher"><span className="workspace-avatar">{(user?.name || "A").slice(0, 1)}</span><span><strong>{demo ? "Demonstração" : user?.name?.split(" ")[0] || "Sua organização"}</strong><small>{demo ? "dados fictícios" : "acesso autenticado"} <span className="live-dot" /></small></span><ChevronRight size={15} /></div><nav className="main-nav"><span className="nav-section">NAVEGAÇÃO</span>{navItems.map(item => { const Icon = item.icon; return <button className={view === item.id ? "active" : ""} key={item.id} onClick={() => switchView(item.id)}><Icon size={17} /><span>{item.label}</span>{item.id === "catalog" && <em>base</em>}</button>; })}</nav><div className="sidebar-bottom"><button onClick={() => toast.info("A central de ajuda será conectada quando o canal de suporte for definido.")}><HelpCircle size={17} /> Ajuda e suporte</button><div className="user-row"><span className="avatar">{(user?.name || "A").slice(0, 1)}</span><span><strong>{demo ? "Conta demonstração" : user?.name || "Usuário"}</strong><small>{demo ? "sem dados reais" : user?.email || "conta conectada"}</small></span><button className="icon-button" onClick={() => demo ? setLocation("/") : logout()} aria-label="Sair"><LogOut size={16} /></button></div></div></aside><main className="app-main"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><Command size={18} /></button><div className="breadcrumbs"><span>AGROLINK</span><ChevronRight size={14} /><strong>{activeLabel}</strong></div><div className="topbar-actions"><div className="top-search"><Search size={16} /><span>Buscar na base</span></div><button className="top-icon" aria-label="Notificações"><Bell size={18} /><i /></button><button className="top-icon" onClick={toggleTheme} aria-label="Alternar tema">{theme === "light" ? <Moon size={18} /> : <Sun size={18} />}</button></div></header><div className="app-content">{demo && <DemoBanner />}{view === "overview" && <DashboardOverview demo={demo} onNavigate={switchView} />}{view === "catalog" && <CatalogView demo={demo} onNavigate={switchView} />}{view === "private" && <PrivateContactsView demo={demo} onNavigate={switchView} />}{view === "imports" && <ImportView demo={demo} onNavigate={switchView} />}{view === "crm" && <CrmView demo={demo} />}{view === "templates" && <TemplatesView demo={demo} />}{view === "settings" && <SettingsView demo={demo} />}{view === "admin" && <AdminCatalogView demo={demo} />}</div></main></div>;
}
